import { Mesh, PlaneGeometry, Vector3, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {number[]} position
 * @property {number[]} rotation
 * @property {number[]} scale
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object[]} cinematicPrimitives
 * @property {Object} atlas
 * @property {number[]} atlas.sourceRect
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string,Function>} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Create a quoted panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  const {
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {},
    cinematicPrimitives = [],
    atlas = {}
  } = config;

  const { imageUrl } = assets;

  // Load texture (synchronous via cached loader)
  const texture = ctx.textureLoader(imageUrl);
  texture.encoding = texture.encoding ?? undefined;
  texture.needsUpdate = true;

  // Determine aspect from source rect (default 512x320)
  const srcRect = atlas.sourceRect || [0, 0, 512, 320];
  const rectWidth = srcRect[2] || 512;
  const rectHeight = srcRect[3] || 320;
  const aspect = rectWidth / rectHeight || 1;

  // Geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  material.map = texture;
  material.transparent = true;

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.name = config.id || 'quote-panel';

  // Apply positioning
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);

  // Apply scaling: keep Y scale from config, X scaled by aspect
  mesh.scale.set(aspect * scale[0], scale[1], scale[2]);

  // Store base Y for hover animation
  const baseY = position[1];
  let hoverTween = null;

  // Event handlers
  mesh.userData.handlers = {
    hoverEnter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    hoverLeave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    click: () => {
      ctx.emit?.('hub-journal.select');
    }
  };

  // Apply cinematic primitives
  cinematicPrimitives.forEach((prim) => {
    const fn = ctx.primitives && ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      fn(mesh, prim.params || {});
    }
  });

  // Cleanup routine
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    material.dispose();
    if (texture && typeof texture.dispose === 'function') {
      texture.dispose();
    }
  };

  return mesh;
}
